-- Core: extensions, shared helpers, user profile, settings, consents.
--
-- Conventions for every table (see docs/PROJECT.md §6):
--   * ids are UUIDs generated by the client (default only as a fallback)
--   * created_at / updated_at / deleted_at on every table (soft delete, ready for offline sync)
--   * metric units only, `day` columns are the user's local date
--   * RLS enabled on every table (policies are in 20261008100400_rls_storage.sql)

create extension if not exists pg_trgm with schema extensions;

-- Keeps updated_at honest: always set by the server, never trusted from the client.
create function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- profiles: one row per auth user, created empty at sign-up and filled by onboarding.
-- ---------------------------------------------------------------------------
create table public.profiles (
  id                      uuid primary key references auth.users (id) on delete cascade,
  name                    text,
  birth_date              date,
  -- Used only by the Mifflin-St Jeor formula, which has two variants.
  sex                     text check (sex in ('male', 'female')),
  height_cm               numeric(5, 1) check (height_cm between 50 and 260),
  -- Daily activity outside training (Personal info screen): Mostly sitting / Light /
  -- On my feet / Physical job.
  activity_level          text check (activity_level in ('sedentary', 'light', 'active', 'physical')),
  experience              text check (experience in ('beginner', 'intermediate', 'advanced')),
  training_location       text check (training_location in ('gym', 'home', 'bodyweight')),
  goal                    text check (goal in ('lose_fat', 'maintain', 'build_muscle')),
  timezone                text not null default 'UTC',
  -- Which Diet screen to show: Food log (count foods) or Fixed meals.
  diet_mode               text not null default 'tracking' check (diet_mode in ('tracking', 'fixed_meals')),
  onboarding_completed_at timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  deleted_at              timestamptz
);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- user_settings: units, look, accessibility, notifications.
-- ---------------------------------------------------------------------------
create table public.user_settings (
  user_id          uuid primary key references auth.users (id) on delete cascade,
  weight_unit      text not null default 'kg' check (weight_unit in ('kg', 'lb')),
  length_unit      text not null default 'cm' check (length_unit in ('cm', 'ft_in')),
  energy_unit      text not null default 'kcal' check (energy_unit in ('kcal', 'kj')),
  week_start       text not null default 'mon' check (week_start in ('mon', 'sun')),
  accent           text not null default 'red'
                   check (accent in ('red', 'orange', 'yellow', 'green', 'blue', 'white')),
  theme            text not null default 'dark' check (theme in ('dark', 'light', 'system')),
  language         text not null default 'en',
  -- Accessibility screen: text size is 1..5 (3 = default).
  text_scale       smallint not null default 3 check (text_scale between 1 and 5),
  bold_text        boolean not null default false,
  dot_numbers      boolean not null default true,
  high_contrast    boolean not null default false,
  reduce_motion    boolean not null default false,
  haptics          boolean not null default true,
  one_hand_mode    boolean not null default false,
  spoken_countdown boolean not null default false,
  -- Size of one "glass" in the water quick-log (Today shows glasses, the DB stores ml).
  water_glass_ml   integer not null default 250 check (water_glass_ml between 50 and 2000),
  notifications    jsonb not null default jsonb_build_object(
                     'rest_timer', true,
                     'workout_reminder', true,
                     'weekly_check_in', true,
                     'meals', false
                   ),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  deleted_at       timestamptz
);

create trigger user_settings_set_updated_at
  before update on public.user_settings
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- consents: health data (GDPR art. 9) and optional analytics. Rows are never deleted by the
-- user: withdrawing sets withdrawn_at, so there is an audit trail.
-- ---------------------------------------------------------------------------
create table public.consents (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  type           text not null check (type in ('health_data', 'analytics')),
  policy_version text not null,
  granted_at     timestamptz not null default now(),
  withdrawn_at   timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz
);

create index consents_user_idx on public.consents (user_id, type);

create trigger consents_set_updated_at
  before update on public.consents
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- New auth user -> empty profile + default settings.
-- ---------------------------------------------------------------------------
create function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id) values (new.id);
  insert into public.user_settings (user_id) values (new.id);
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();
